package goguitarpro
import("strings";"testing")
func TestReviewVolumeConsumerPrerequisite(t *testing.T){
 song:=semanticValidPitchedGP8Song(t)
 data,err:=Export(song,ExportFormatGP8);if err!=nil{t.Fatal(err)}
 source:=rewriteConformanceGPIF(t,data,func(s string)string{return strings.Replace(s,"</ChannelStrip>",`<Automations><Automation><Type>DSPParam_12</Type><Bar>0</Bar><Position>0.25</Position><Linear>false</Linear><Value>0.25</Value></Automation><Automation><Type>DSPParam_12</Type><Bar>0</Bar><Position>0.75</Position><Linear>true</Linear><Value>0.875</Value></Automation></Automations></ChannelStrip>`,1)})
 parsed,err:=Parse(source);if err!=nil{t.Fatal(err)}
 if len(parsed.VolumeAutomations)!=2{t.Fatalf("Go source events=%#v",parsed.VolumeAutomations)}
 facts:=readAlphaTabScore(t,writeConformanceFixture(t,source))
 count:=0
 var visit func(any)
 visit=func(v any){switch x:=v.(type){case map[string]any: if x["type"]=="volume"{count++};for _,c:=range x{visit(c)};case []any:for _,c:=range x{visit(c)}}}
 visit(facts)
 t.Logf("Go events=%#v; pinned volume automation count=%d",parsed.VolumeAutomations,count)
 if count!=2{t.Fatalf("required independent volume events=%d, want 2",count)}
}
